using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering.Universal;using Newtonsoft.Json.Linq;
public static class CDCapture {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string O=>R+"/Docs/Review/2026-11-10_B2_CeilingDensity/";
 static void Shot(string n,Vector3 p,Vector3 t,bool inspect=false){var g=new GameObject("CD_ReviewCamera"){hideFlags=HideFlags.HideAndDontSave};var c=g.AddComponent<Camera>();c.transform.position=p;c.transform.LookAt(t);if(inspect){var l=g.AddComponent<Light>();l.type=LightType.Spot;l.color=new Color(1,.82f,.68f);l.intensity=20;l.range=27;l.spotAngle=110;l.shadows=LightShadows.Soft;}c.nearClipPlane=.05f;c.farClipPlane=180;c.fieldOfView=85;c.useOcclusionCulling=false;c.GetUniversalAdditionalCameraData().renderPostProcessing=false;var rt=new RenderTexture(1440,1000,24){antiAliasing=4};var old=RenderTexture.active;Texture2D tex=null;try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;tex=new Texture2D(1440,1000,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1440,1000),0,0);tex.Apply();File.WriteAllBytes(O+n+".png",tex.EncodeToPNG());}finally{RenderTexture.active=old;c.targetTexture=null;if(tex)UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(g);}}
 public static object Before()=>Run("before",false);public static object After()=>Run("after",false);public static object Inspection()=>Run("inspection",true);
 static object Run(string prefix,bool inspect){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_B2_Circular.unity"))throw new Exception("Saved B2 required");Directory.CreateDirectory(O);var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));bool on=player.activeSelf;player.SetActive(false);try{foreach(var r in JObject.Parse(File.ReadAllText(R+"/SourceAssets/B2_CeilingDensity/plan.json"))["rooms"]){string id=(string)r["id"];var origin=new Vector3((float)r["x"],-34,-(float)r["v"]);var door=r["doors"].First();var offset=new Vector3((float)door["x"],0,(float)door["z"]);Shot(prefix+"_roof_"+id,origin+offset*.82f+Vector3.up*1.65f,origin+Vector3.up*((float)r["r"]*.57f),inspect);} if(prefix!="before"){
 Shot(prefix+"_focus_C02",new Vector3(19,-32.35f,-8.7f),new Vector3(19,-29.8f,3),inspect);
 Shot(prefix+"_focus_S01",new Vector3(0,-32.35f,-72.5f),new Vector3(0,-31.4f,-78.5f),inspect);
 Shot(prefix+"_focus_N01",new Vector3(0,-32.35f,71.8f),new Vector3(0,-30.8f,79),inspect);
 } }finally{player.SetActive(on);EditorSceneManager.OpenScene(s.path);}return new{prefix,images=prefix=="before"?12:15,temporaryInspectionLight=inspect};}
}
